<script setup lang="ts">
import{computed,onMounted,ref}from"vue";import CpfIcon from"../../components/CpfIcon.vue";import{bzaApi,hasBzaPermission}from"../auth/session";type Row=Record<string,any>;const rows=ref<Row[]>([]),selected=ref<Row|null>(null),error=ref("");const roots=computed(()=>rows.value.filter(r=>!r.parentOrganizationCode||!rows.value.some(x=>x.organizationCode===r.parentOrganizationCode)));function children(code:any){return rows.value.filter(r=>r.parentOrganizationCode===code)}async function load(){try{rows.value=await bzaApi('/api/bza/backoffice/organizations?limit=500')}catch(e){error.value=e instanceof Error?e.message:String(e)}}onMounted(load);</script>
<template><div class="page-stack"><div class="cpf-page-heading"><div><p class="eyebrow">ORGANIZATION DIRECTORY</p><h2>조직도</h2><p>조직 계층과 운영 상태를 Tree 중심으로 탐색합니다.</p></div><button class="ghost" @click="load"><CpfIcon name="refresh"/> 새로고침</button></div><p v-if="error" class="error-banner">{{error}}</p><div class="bza-org-layout"><section class="cpf-card"><div class="cpf-card-head"><h2>조직 Tree</h2><span class="cpf-status info">{{rows.length}} nodes</span></div><div class="cpf-card-body org-tree"><article v-for="root in roots" :key="String(root.organizationCode)" class="org-node root" @click="selected=root"><div><strong>{{root.organizationName}}</strong><small>{{root.organizationCode}} · {{root.organizationType}}</small></div><span class="cpf-status" :class="root.useYn==='N'?'danger':'success'">{{root.useYn==='N'?'중지':'사용'}}</span><div class="org-children"><button v-for="child in children(root.organizationCode)" :key="String(child.organizationCode)" type="button" class="org-child" @click.stop="selected=child"><span class="org-branch"></span><span><strong>{{child.organizationName}}</strong><small>{{child.organizationCode}}</small></span><span class="cpf-status">{{children(child.organizationCode).length}} 하위</span></button></div></article><div v-if="!roots.length" class="cpf-empty">조직 데이터가 없습니다.</div></div></section><aside class="cpf-card bza-detail-drawer"><div class="cpf-card-head"><h2>조직 상세</h2></div><div v-if="selected" class="detail-list"><dl><dt>조직 코드</dt><dd>{{selected.organizationCode}}</dd><dt>조직명</dt><dd>{{selected.organizationName}}</dd><dt>상위 조직</dt><dd>{{selected.parentOrganizationCode||'ROOT'}}</dd><dt>조직 유형</dt><dd>{{selected.organizationType||'-'}}</dd><dt>사용 여부</dt><dd>{{selected.useYn}}</dd></dl><p class="cpf-note" v-if="hasBzaPermission('ORGANIZATION','WRITE')">변경은 권한과 감사 사유가 적용되는 조직 편집 기능에서 수행합니다.</p></div><div v-else class="cpf-empty">Tree에서 조직을 선택하세요.</div></aside></div></div></template>